namespace LIS2.App.Avalonia;

/// <summary>Hilfetexte für Deutsch, Französisch, Türkisch und Russisch; Englisch ist die Quellsprache.</summary>
internal static class HelpReferenceLocalization
{
    private static readonly IReadOnlyDictionary<string, string[]> Texts = new Dictionary<string, string[]>(StringComparer.Ordinal)
    {
        ["Windows CPU temperatures"] = ["CPU-Temperaturen unter Windows", "Températures CPU sous Windows", "Windows CPU sıcaklıkları", "Температуры CPU в Windows"],
        ["Windows CPU temperatures require the official signed PawnIO driver used by LibreHardwareMonitor. To run without administrator rights, explicitly grant PawnIO access to your Windows account once using tools/windows/Set-PawnIoUserAccess.ps1; installation and permission changes require elevation. This grants driver access to all programs under that account, not only LIS2 or temperature reads. Restart the application normally afterwards. Setup, verification and rollback: https://github.com/Eitschman/lis2-control-center/blob/main/docs/windows-hardware-sensors.md. Missing access can leave CPU temperatures unavailable while GPU readings still work; ACPI thermal zones are not CPU sensors."] = [
            "CPU-Temperaturen unter Windows benötigen den offiziellen signierten PawnIO-Treiber für LibreHardwareMonitor. Für den Betrieb ohne Administratorrechte den Zugriff einmalig ausdrücklich für das eigene Windows-Konto mit tools/windows/Set-PawnIoUserAccess.ps1 freigeben. Installation und Rechteänderung benötigen Administratorrechte. Die Freigabe gilt für alle Programme dieses Kontos und ist nicht auf LIS2 oder Temperaturabfragen beschränkt. Danach die Anwendung normal neu starten. Einrichtung, Prüfung und Rücknahme: https://github.com/Eitschman/lis2-control-center/blob/main/docs/windows-hardware-sensors.md. Ohne Zugriff können CPU-Werte fehlen, obwohl GPU-Werte verfügbar sind; ACPI-Thermalzonen sind keine CPU-Sensoren.",
            "Les températures CPU nécessitent le pilote officiel signé PawnIO de LibreHardwareMonitor. Pour utiliser l’application sans droits administrateur, autorisez explicitement votre compte Windows une fois avec tools/windows/Set-PawnIoUserAccess.ps1. L’installation et les permissions nécessitent une élévation. L’accès concerne tous les programmes du compte, pas uniquement LIS2 ou les températures. Redémarrez ensuite normalement. Installation, vérification et restauration : https://github.com/Eitschman/lis2-control-center/blob/main/docs/windows-hardware-sensors.md. Sans accès, les valeurs CPU peuvent manquer alors que celles du GPU restent disponibles ; les zones ACPI ne sont pas des capteurs CPU.",
            "CPU sıcaklıkları için LibreHardwareMonitor tarafından kullanılan resmî imzalı PawnIO sürücüsü gerekir. Yönetici olmadan çalıştırmak için tools/windows/Set-PawnIoUserAccess.ps1 ile Windows hesabınıza bir kez açıkça erişim verin. Kurulum ve izin değişikliği yönetici hakları gerektirir. İzin, hesabın tüm programları için geçerlidir; yalnızca LIS2 veya sıcaklık okumalarıyla sınırlı değildir. Ardından uygulamayı normal yeniden başlatın. Kurulum, kontrol ve geri alma: https://github.com/Eitschman/lis2-control-center/blob/main/docs/windows-hardware-sensors.md. Erişim olmadan GPU değerleri çalışırken CPU değerleri eksik kalabilir; ACPI bölgeleri CPU sensörü değildir.",
            "Для температур CPU нужен официальный подписанный драйвер PawnIO для LibreHardwareMonitor. Для работы без прав администратора один раз явно разрешите доступ своей учётной записи Windows через tools/windows/Set-PawnIoUserAccess.ps1. Установка и изменение прав требуют повышения привилегий. Доступ получают все программы этой учётной записи, а не только LIS2 или чтение температур. Затем запустите приложение обычным способом. Настройка, проверка и отмена: https://github.com/Eitschman/lis2-control-center/blob/main/docs/windows-hardware-sensors.md. Без доступа значения CPU могут отсутствовать при доступных значениях GPU; зоны ACPI не являются датчиками CPU."],
        ["Current page"] = ["Aktuelle Seite", "Page actuelle", "Geçerli sayfa", "Текущая страница"],
        ["Regional numbers"] = ["Regionale Zahlenformate", "Formats numériques régionaux", "Bölgesel sayı biçimleri", "Региональные числовые форматы"],
        ["All source numbers use the operating system regional settings, independently of the interface language. Hardware, Home Assistant and variable browsers use the same presentation. Numeric Home Assistant states retain their decimal places without an explicit format. Titles, text attributes, dates, timelines, source keys and technical input syntax remain unchanged. Use number, percent or bytes in a template to choose precision."] = [
            "Zahlen aller Quellen folgen den Regionseinstellungen des Betriebssystems, unabhängig von der Oberflächensprache. Hardware-, Home-Assistant- und Variablenbrowser verwenden dieselbe Darstellung. Numerische HA-Zustände behalten ohne ausdrückliches Format ihre Nachkommastellen. Titel, Textattribute, Datums- und Laufzeitformate, Quellschlüssel und technische Eingabesyntax bleiben unverändert. Die Genauigkeit lässt sich mit number, percent oder bytes in der Vorlage wählen.",
            "Les nombres de toutes les sources suivent les paramètres régionaux du système, indépendamment de la langue de l’interface. Les navigateurs Matériel, Home Assistant et variables utilisent la même présentation. Les états numériques HA conservent leurs décimales sans format explicite. Titres, attributs textuels, dates, durées, clés et syntaxe technique restent inchangés. Choisissez la précision avec number, percent ou bytes dans le modèle.",
            "Tüm kaynakların sayıları arayüz dilinden bağımsız olarak işletim sisteminin bölgesel ayarlarını izler. Donanım, Home Assistant ve değişken tarayıcıları aynı gösterimi kullanır. Sayısal HA durumları açık biçim olmadan ondalık basamaklarını korur. Başlıklar, metin öznitelikleri, tarihler, süreler, kaynak anahtarları ve teknik giriş sözdizimi değişmez. Hassasiyet için şablonda number, percent veya bytes kullanın.",
            "Числа всех источников используют региональные настройки системы независимо от языка интерфейса. Обозреватели оборудования, Home Assistant и переменных используют одинаковое представление. Числовые состояния HA сохраняют знаки после запятой без явного формата. Названия, текстовые атрибуты, даты, время воспроизведения, ключи и технический синтаксис не меняются. Для выбора точности используйте number, percent или bytes в шаблоне."],
        ["Home Assistant numbers"] = ["Home-Assistant-Zahlen", "Nombres Home Assistant", "Home Assistant sayıları", "Числа Home Assistant"],
        ["Numeric entity states, including aliases and fallback variables, use the operating system decimal separator in templates without rounding. For example, 21.50 becomes 21,50 with German regional settings. Explicit number, percent and bytes formats control precision. Raw states, visibility expressions, text attributes and names remain unchanged; numeric JSON attributes already follow regional settings."] = [
            "Numerische Entitätszustände verwenden in Vorlagen das Dezimaltrennzeichen des Betriebssystems, auch über Aliase und Ersatzvariablen und ohne Rundung. Beispielsweise wird 21.50 bei deutschen Regionseinstellungen zu 21,50. Ausdrückliche Formate mit number, percent und bytes bestimmen die Genauigkeit. Rohzustände, Sichtbarkeitsausdrücke, Textattribute und Namen bleiben unverändert; numerische JSON-Attribute folgen bereits den Regionseinstellungen.",
            "Les états numériques utilisent le séparateur décimal du système dans les modèles, y compris via les alias et variables de remplacement, sans arrondi. Par exemple, 21.50 devient 21,50 avec les paramètres régionaux allemands. Les formats explicites number, percent et bytes contrôlent la précision. États bruts, expressions de visibilité, attributs textuels et noms restent inchangés ; les attributs JSON numériques suivent déjà les paramètres régionaux.",
            "Sayısal varlık durumları, takma adlar ve yedek değişkenler dahil, şablonlarda yuvarlanmadan işletim sisteminin ondalık ayırıcısını kullanır. Örneğin Alman bölgesel ayarlarında 21.50 yerine 21,50 gösterilir. Açık number, percent ve bytes biçimleri hassasiyeti belirler. Ham durumlar, görünürlük ifadeleri, metin öznitelikleri ve adlar değişmez; sayısal JSON öznitelikleri bölgesel ayarları zaten izler.",
            "Числовые состояния сущностей в шаблонах используют десятичный разделитель системы без округления, включая псевдонимы и резервные переменные. Например, 21.50 отображается как 21,50 при немецких региональных настройках. Явные форматы number, percent и bytes задают точность. Исходные состояния, выражения видимости, текстовые атрибуты и имена не меняются; числовые атрибуты JSON уже используют региональные настройки."],
        ["Live values"] = ["Livewerte", "Valeurs en direct", "Canlı değerler", "Текущие значения"],
        ["The Dashboard combines the compact 20x2 VFD preview, page controls, four fan channels and eight configurable live values. Connection status remains in the header."] = [
            "Die Übersicht kombiniert die kompakte 20x2-VFD-Vorschau, Seitensteuerung, vier Lüfterkanäle und acht konfigurierbare Livewerte. Der Verbindungsstatus bleibt im Kopfbereich.",
            "Le tableau de bord réunit l’aperçu VFD compact 20x2, les commandes de pages, quatre ventilateurs et huit valeurs configurables. La connexion reste affichée en haut.",
            "Gösterge paneli kompakt 20x2 VFD önizlemesini, sayfa denetimini, dört fan kanalını ve sekiz yapılandırılabilir canlı değeri birleştirir. Bağlantı durumu üstte kalır.",
            "Панель объединяет компактный предпросмотр VFD 20x2, управление страницами, четыре вентилятора и восемь настраиваемых значений. Состояние подключения остаётся в заголовке."],
        ["Choose an enabled, currently visible page or use Previous and Next while the sequence is running. Pause stops only automatic page rotation; live values, scrolling and event overlays continue. Resume continues rotation. These controls use the applied virtual or serial transport; they are disabled when playback is stopped."] = [
            "Bei laufender Seitenfolge eine aktivierte, aktuell sichtbare Seite wählen oder Vorherige/Nächste Seite verwenden. Pause hält nur die automatische Rotation an; Livewerte, Laufschrift und Ereignis-Overlays laufen weiter. Fortsetzen aktiviert die Rotation wieder. Die Bedienung verwendet den angewendeten virtuellen oder seriellen Transport und ist bei gestoppter Folge gesperrt.",
            "Pendant la séquence, choisissez une page activée et visible ou utilisez Précédente/Suivante. Pause suspend uniquement la rotation automatique ; valeurs, défilement et événements continuent. Reprendre réactive la rotation. Les commandes utilisent le transport virtuel ou série appliqué et sont désactivées à l’arrêt.",
            "Sıra çalışırken etkin ve görünür bir sayfa seçin veya Önceki/Sonraki düğmelerini kullanın. Duraklat yalnızca otomatik dönüşü durdurur; canlı değerler, kayan yazı ve olaylar sürer. Sürdür dönüşü yeniden başlatır. Denetimler uygulanan sanal veya seri bağlantıyı kullanır; sıra durduğunda devre dışıdır.",
            "Во время показа выберите включённую видимую страницу или используйте Предыдущая/Следующая. Пауза останавливает только автоматическую смену; данные, прокрутка и события продолжаются. Возобновление включает смену снова. Используется применённый виртуальный или последовательный транспорт; при остановке показа кнопки отключены."],
        ["Each channel shows its configured mode and control sensor. Use the gear beside Fan Outputs to assign a real RPM sensor to each channel. The LIS2 does not supply confirmed RPM feedback. Unassigned speed sensors show —; configured sensors without data show Unavailable. Assigning a sensor never authorizes hardware output."] = [
            "Jeder Kanal zeigt den konfigurierten Modus und Regelsensor. Über das Zahnrad bei Lüfterausgänge jedem Kanal einen echten Drehzahlsensor zuordnen. Das LIS2 liefert keine bestätigte Drehzahlrückmeldung. Nicht zugeordnete Sensoren zeigen —; konfigurierte Sensoren ohne Daten zeigen Nicht verfügbar. Die Sensorzuordnung erteilt keine Hardwarefreigabe.",
            "Chaque canal affiche le mode configuré et le capteur de commande. La roue dentée des ventilateurs permet d’affecter un vrai capteur RPM. Le LIS2 ne fournit pas de retour RPM confirmé. Les capteurs non affectés affichent — ; les capteurs configurés sans données affichent Indisponible. L’affectation n’autorise jamais la sortie matérielle.",
            "Her kanal yapılandırılmış modu ve denetim sensörünü gösterir. Fan çıkışlarının dişli düğmesiyle gerçek bir RPM sensörü atayın. LIS2 doğrulanmış devir geri bildirimi sağlamaz. Atanmamış sensörler —, verisi olmayan yapılandırılmış sensörler Kullanılamıyor gösterir. Sensör ataması donanım çıkışına izin vermez.",
            "Канал показывает настроенный режим и датчик управления. Шестерёнка выходов назначает реальный датчик RPM. LIS2 не предоставляет подтверждённую обратную связь об оборотах. Неназначенные датчики показывают —; настроенные датчики без данных показывают Недоступно. Назначение не разрешает управление оборудованием."],
        ["Use the gear beside Live values to configure eight labels and templates. Browse variables inserts a current source key; existing template formatting is supported, for example {Hardware.Cpu.Temperature|number:1|suffix: °C}. Choose actual keys from your system. Unconfigured slots show —; configured templates without results show Unavailable. Compact numbers changes explicit numeric formats to at most one decimal place and adds spaces before units in the draft; Save applies the changes. Existing templates remain unchanged unless you choose this action. Save persists the selection; Cancel discards edits. These values are independent of the active display page."] = [
            "Über das Zahnrad bei Livewerte acht Beschriftungen und Vorlagen konfigurieren. Variablen durchsuchen fügt einen aktuellen Quellschlüssel ein. Die bekannte Formatierung gilt, etwa {Hardware.Cpu.Temperature|number:1|suffix: °C}; tatsächliche Schlüssel des eigenen Systems wählen. Unbelegte Felder zeigen —; konfigurierte Vorlagen ohne Ergebnis zeigen Nicht verfügbar. Zahlen kompakt begrenzt ausdrückliche Zahlenformate im Entwurf auf eine Nachkommastelle und ergänzt Leerzeichen vor Einheiten. Speichern übernimmt die Änderungen. Ohne diese Aktion bleiben bestehende Vorlagen unverändert. Speichern sichert die Auswahl, Abbrechen verwirft den Entwurf. Die Werte sind unabhängig von der aktiven Displayseite.",
            "La roue dentée des valeurs configure huit libellés et modèles. Parcourir les variables insère une clé actuelle. Le formatage habituel s’applique, par exemple {Hardware.Cpu.Temperature|number:1|suffix: °C} ; choisissez les clés réelles du système. Les champs non configurés affichent — ; les modèles configurés sans résultat affichent Indisponible. Nombres compacts limite les formats numériques explicites du brouillon à une décimale et ajoute des espaces avant les unités. Enregistrer applique les modifications. Sans cette action, les modèles restent inchangés. Enregistrer conserve le choix, Annuler abandonne les modifications. Ces valeurs ne dépendent pas de la page affichée.",
            "Canlı değerlerin dişli düğmesiyle sekiz etiket ve şablon yapılandırın. Değişkenleri gözat geçerli anahtarı ekler. Örneğin {Hardware.Cpu.Temperature|number:1|suffix: °C} biçimlendirmesi desteklenir; sisteminizin gerçek anahtarlarını seçin. Yapılandırılmamış alanlar —, sonuçsuz yapılandırılmış şablonlar Kullanılamıyor gösterir. Kısa sayılar taslaktaki açık sayı biçimlerini en fazla bir ondalık basamakla sınırlar ve birimlerden önce boşluk ekler. Kaydet değişiklikleri uygular. Bu işlem seçilmezse mevcut şablonlar değişmez. Kaydet seçimi saklar, İptal değişiklikleri atar. Değerler etkin ekran sayfasından bağımsızdır.",
            "Шестерёнка текущих значений настраивает восемь подписей и шаблонов. Обзор переменных вставляет текущий ключ. Поддерживается форматирование, например {Hardware.Cpu.Temperature|number:1|suffix: °C}; выбирайте реальные ключи системы. Ненастроенные поля показывают —; настроенные шаблоны без результата показывают Недоступно. Краткие числа ограничивают явные числовые форматы в черновике одним знаком и добавляют пробелы перед единицами. Сохранение применяет изменения. Без выбора этого действия шаблоны не меняются. Сохранение запоминает выбор, Отмена отклоняет изменения. Значения независимы от активной страницы дисплея."],
        ["Fallback variable"] = ["Ersatzvariable", "Variable de remplacement", "Yedek değişken", "Резервная переменная"],
        ["Stream metadata"] = ["Stream-Metadaten", "Métadonnées du flux", "Yayın meta verileri", "Метаданные потока"],
        ["Use fallbackvar with a variable key without braces. The first available value is used: the main variable, then fallback variables from left to right, then the literal fallback text. Missing, empty, unknown and unavailable values are skipped; zero, false and spaces remain valid. Variable values receive the formatting pipeline; literal fallback text is returned unchanged. Variable values are not evaluated as templates. In the formatting editor, choose Fallback variable with its browser and enter Missing value as the final text."] = [
            "fallbackvar erhält einen Variablenschlüssel ohne Klammern. Verwendet wird der erste verfügbare Wert: Hauptvariable, danach Ersatzvariablen von links nach rechts, zuletzt der feste Ersatztext. Fehlende, leere, unknown und unavailable Werte werden übersprungen; Null, false und Leerzeichen bleiben gültig. Variablenwerte durchlaufen die Formatierung, fester Ersatztext bleibt unverändert. Variablenwerte werden nicht als Vorlagen ausgewertet. Im Formatierungseditor Ersatzvariable über deren Browser wählen und Ersatz bei fehlendem Wert als letzten Text eingeben.",
            "fallbackvar reçoit une clé sans accolades. Priorité : variable principale, variables de remplacement de gauche à droite, puis texte fixe. Les valeurs absentes, vides, unknown ou unavailable sont ignorées ; zéro, false et espaces restent valides. Les variables suivent le formatage ; le texte fixe reste inchangé. Leur contenu n’est pas évalué comme modèle. Dans l’éditeur, choisissez Variable de remplacement avec son navigateur et saisissez Valeur absente comme dernier texte.",
            "fallbackvar, süslü parantezsiz bir değişken anahtarı alır. Önce ana değişken, sonra soldan sağa yedek değişkenler, son olarak sabit yedek metin kullanılır. Eksik, boş, unknown ve unavailable değerler atlanır; sıfır, false ve boşluklar geçerlidir. Değişken değerleri biçimlendirilir; sabit yedek metin değişmez. Değerler şablon olarak değerlendirilmez. Düzenleyicide Yedek değişken alanını tarayıcıyla seçin ve Eksik değer alanına son metni girin.",
            "fallbackvar принимает ключ без фигурных скобок. Порядок: основная переменная, резервные переменные слева направо, затем постоянный текст. Отсутствующие, пустые, unknown и unavailable значения пропускаются; ноль, false и пробелы допустимы. Значения переменных форматируются, постоянный текст не меняется. Содержимое переменных не вычисляется как шаблон. В редакторе выберите резервную переменную через обозреватель и задайте текст для отсутствующего значения."],
        ["Local files use their tags. Streams expose StreamName, StreamTitle, StreamGenre, StreamUrl and IsStream. Title prefers the current StreamTitle, then title metadata, then the playlist display text. Artist is never replaced automatically or split from StreamTitle. Missing decoder fields remain empty. Unicode is preserved. Diagnostics includes TitleSource. Install the matching new gen_lis2.dll; older plug-ins do not supply these fields."] = [
            "Lokale Dateien verwenden ihre Tags. Streams liefern StreamName, StreamTitle, StreamGenre, StreamUrl und IsStream. Title verwendet zuerst den aktuellen StreamTitle, dann Titelmetadaten, zuletzt den Playlist-Anzeigetext. Artist wird nicht automatisch ersetzt oder aus StreamTitle aufgeteilt. Fehlende Decoderfelder bleiben leer. Unicode bleibt erhalten. Die Diagnose enthält TitleSource. Die passende neue gen_lis2.dll installieren; ältere Plug-ins liefern diese Felder nicht.",
            "Les fichiers locaux utilisent leurs tags. Les flux proposent StreamName, StreamTitle, StreamGenre, StreamUrl et IsStream. Title privilégie StreamTitle, puis les métadonnées de titre, puis le texte de la liste. Artist n’est jamais remplacé automatiquement ni extrait de StreamTitle. Les champs absents restent vides. Unicode est conservé. Le diagnostic inclut TitleSource. Installez la nouvelle gen_lis2.dll ; les anciens plug-ins ne fournissent pas ces champs.",
            "Yerel dosyalar etiketlerini kullanır. Yayınlar StreamName, StreamTitle, StreamGenre, StreamUrl ve IsStream sağlar. Title önce StreamTitle, sonra başlık meta verisi, son olarak çalma listesi metnini kullanır. Artist otomatik değiştirilmez veya StreamTitle içinden ayrılmaz. Eksik alanlar boş kalır. Unicode korunur. Tanılama TitleSource içerir. Yeni gen_lis2.dll dosyasını kurun; eski eklentiler bu alanları sağlamaz.",
            "Локальные файлы используют теги. Потоки предоставляют StreamName, StreamTitle, StreamGenre, StreamUrl и IsStream. Title выбирает StreamTitle, затем метаданные названия, затем текст списка. Artist автоматически не заменяется и не выделяется из StreamTitle. Отсутствующие поля остаются пустыми. Unicode сохраняется. Диагностика содержит TitleSource. Установите новую gen_lis2.dll; старые плагины не передают эти поля."],
        ["Modern player subtitles"] = ["Untertitel des modernen Players", "Sous-titres du lecteur moderne", "Modern oynatıcı alt başlıkları", "Подзаголовки современного проигрывателя"],
        ["Legacy radio metadata"] = ["Legacy-Radiometadaten", "Métadonnées radio Legacy", "Legacy radyo meta verileri", "Радиометаданные Legacy"],
        ["Linux stream metadata"] = ["Linux-Streammetadaten", "Métadonnées des flux Linux", "Linux yayın meta verileri", "Метаданные потоков Linux"],
        ["WindowsMedia.Subtitle exposes the subtitle supplied by GSMTC. It is not a guaranteed station name. Windows does not expose a separate station name or stream URL through this interface. Artist and Title remain unchanged. Select Subtitle explicitly as a fallback variable if useful; missing subtitles remain unavailable."] = [
            "WindowsMedia.Subtitle liefert den von GSMTC bereitgestellten Untertitel. Das ist kein zugesicherter Sendername. Windows stellt über diese Schnittstelle weder einen eigenen Sendernamen noch eine Stream-URL bereit. Artist und Title bleiben unverändert. Subtitle kann bei Bedarf ausdrücklich als Ersatzvariable ausgewählt werden; fehlende Untertitel bleiben nicht verfügbar.",
            "WindowsMedia.Subtitle fournit le sous-titre transmis par GSMTC. Ce n’est pas nécessairement un nom de station. Cette interface Windows n’expose ni station ni URL de flux distincte. Artist et Title restent inchangés. Sélectionnez explicitement Subtitle comme variable de remplacement si utile ; les sous-titres absents restent indisponibles.",
            "WindowsMedia.Subtitle, GSMTC tarafından sağlanan alt başlığı sunar. İstasyon adı olması garanti değildir. Bu Windows arayüzü ayrı istasyon adı veya yayın adresi sağlamaz. Artist ve Title değişmez. Gerekirse Subtitle öğesini açıkça yedek değişken seçin; eksik alt başlıklar kullanılamaz.",
            "WindowsMedia.Subtitle передаёт подзаголовок GSMTC. Это не обязательно название станции. Этот интерфейс Windows не предоставляет отдельное название станции или URL потока. Artist и Title не изменяются. При необходимости явно выберите Subtitle как резервную переменную; отсутствующие подзаголовки остаются недоступными."],
        ["WmpLegacy.StreamName reads WM/RadioStationName from the current network media. StreamUrl is its playback URL; IsStream identifies a non-file URL. Missing station metadata remains empty: neither the title nor the URL is invented as a station name. Artist keeps its real tags. Use StreamName explicitly as a fallback variable. Install the new background plug-in matching the player architecture; older DLLs do not provide these values. Switching to a local file clears the stream fields."] = [
            "WmpLegacy.StreamName liest WM/RadioStationName des aktuellen Netzwerkmediums. StreamUrl ist dessen Wiedergabeadresse; IsStream kennzeichnet eine Nicht-Datei-URL. Fehlende Sendermetadaten bleiben leer: Weder Titel noch URL werden als Sendername ausgegeben. Artist behält die echten Tags. StreamName kann ausdrücklich als Ersatzvariable dienen. Das neue Hintergrund-Plug-in muss zur Playerarchitektur passen; ältere DLLs liefern diese Werte nicht. Beim Wechsel zu einer lokalen Datei werden die Streamfelder geleert.",
            "WmpLegacy.StreamName lit WM/RadioStationName du média réseau actuel. StreamUrl est son URL de lecture ; IsStream signale une URL réseau. Les stations absentes restent vides : ni titre ni URL ne sont utilisés comme nom de station. Artist conserve les vrais tags. Choisissez explicitement StreamName comme variable de remplacement. Installez le nouveau plug-in de fond adapté au lecteur ; les anciennes DLL ne fournissent pas ces valeurs. Un fichier local efface les champs de flux.",
            "WmpLegacy.StreamName, geçerli ağ ortamının WM/RadioStationName değerini okur. StreamUrl oynatma adresidir; IsStream ağ adresini belirtir. Eksik istasyon bilgileri boş kalır; başlık veya adres istasyon adı olarak kullanılmaz. Artist gerçek etiketleri korur. StreamName öğesini açıkça yedek değişken seçin. Oynatıcı mimarisine uygun yeni arka plan eklentisini kurun; eski DLL’ler bu değerleri sağlamaz. Yerel dosyaya geçiş yayın alanlarını temizler.",
            "WmpLegacy.StreamName читает WM/RadioStationName текущего сетевого медиа. StreamUrl содержит адрес воспроизведения; IsStream обозначает сетевой URL. Отсутствующие данные станции остаются пустыми: название и URL не выдаются за станцию. Artist сохраняет настоящие теги. Явно выберите StreamName как резервную переменную. Установите новый фоновый плагин нужной архитектуры; старые DLL не передают эти значения. При переходе к локальному файлу поля потока очищаются."],
        ["Media.Artist and Media.Title preserve the values published by the selected MPRIS player. Tuner may publish the station name as Artist when track artist metadata is missing. LIS2 does not split combined titles or invent a station name; MPRIS has no standard station-name field. Normal music-file artist tags remain unchanged. If Artist is empty, use a literal fallback or another explicitly selected variable."] = [
            "Media.Artist und Media.Title übernehmen die Werte des ausgewählten MPRIS-Players unverändert. Tuner kann bei fehlendem Titelinterpreten den Sendernamen als Artist liefern. LIS2 teilt zusammengesetzte Titel nicht auf und erfindet keinen Sendernamen; MPRIS besitzt kein standardisiertes Senderfeld. Interpretentags normaler Musikdateien bleiben unverändert. Bei leerem Artist kann ein fester Ersatztext oder eine andere ausdrücklich ausgewählte Variable verwendet werden.",
            "Media.Artist et Media.Title conservent les valeurs du lecteur MPRIS sélectionné. Tuner peut fournir la station comme Artist si l’artiste manque. LIS2 ne découpe pas les titres combinés et n’invente pas de station ; MPRIS n’a pas de champ standard pour son nom. Les tags des fichiers musicaux restent inchangés. Si Artist est vide, utilisez un texte ou une autre variable explicitement choisie.",
            "Media.Artist ve Media.Title, seçilen MPRIS oynatıcısının değerlerini değiştirmeden korur. Sanatçı bilgisi yoksa Tuner, Artist alanında istasyon adını sağlayabilir. LIS2 birleşik başlıkları bölmez veya istasyon adı üretmez; MPRIS standart istasyon alanı içermez. Normal müzik dosyalarının sanatçı etiketleri değişmez. Artist boşsa sabit metin veya açıkça seçilen başka bir değişken kullanın.",
            "Media.Artist и Media.Title сохраняют значения выбранного MPRIS-проигрывателя. Tuner может передавать станцию в Artist, если исполнитель отсутствует. LIS2 не разделяет составные названия и не выдумывает станцию; в MPRIS нет стандартного поля станции. Теги исполнителей музыкальных файлов не изменяются. При пустом Artist используйте текст замены или другую явно выбранную переменную."],
        ["Formatting editor"] = ["Formatierungseditor", "Éditeur de formatage", "Biçimlendirme düzenleyicisi", "Редактор форматирования"],
        ["Formatting examples"] = ["Formatierungsbeispiele", "Exemples de formatage", "Biçimlendirme örnekleri", "Примеры форматирования"],
        ["Numbers"] = ["Zahlen", "Nombres", "Sayılar", "Числа"],
        ["Percent"] = ["Prozent", "Pourcentage", "Yüzde", "Проценты"],
        ["Bytes"] = ["Bytes", "Octets", "Bayt", "Байты"],
        ["Text"] = ["Text", "Texte", "Metin", "Текст"],
        ["Missing values"] = ["Fehlende Werte", "Valeurs absentes", "Eksik değerler", "Отсутствующие значения"],
        ["Expand Formatting editor on Pages. Enter a variable key without braces or select it with Browse variables. Choose Unchanged, Number, Percent or Bytes, set 0 to 6 decimal places and optionally choose letter case, prefix, suffix and missing-value text. Template shows the generated expression; Current result uses live source values. Insert into line 1 or 2 inserts at that field's caret. Save page to persist the changed template; the helper settings themselves are not saved. Free editing remains available. F1 in either line field opens its formatting hint; Escape closes it."] = [
            "Unter Seiten den Formatierungseditor aufklappen. Einen Variablenschlüssel ohne Klammern eingeben oder mit Variablen durchsuchen wählen. Unverändert, Zahl, Prozent oder Bytes wählen, 0 bis 6 Nachkommastellen einstellen und bei Bedarf Groß-/Kleinschreibung, Präfix, Suffix und Ersatztext festlegen. Vorlagenausdruck zeigt die erzeugte Syntax; Aktuelles Ergebnis verwendet Livewerte. In Zeile 1 oder 2 einfügen setzt den Ausdruck an deren Schreibmarke ein. Seite speichern sichert die geänderte Vorlage; die Hilfseditor-Einstellungen selbst werden nicht gespeichert. Freies Bearbeiten bleibt möglich. F1 im Zeilenfeld öffnet den Formatierungshinweis, Escape schließt ihn.",
            "Dans Pages, ouvrez Éditeur de formatage. Saisissez une clé sans accolades ou utilisez Parcourir les variables. Choisissez Inchangé, Nombre, Pourcentage ou Octets, 0 à 6 décimales, puis éventuellement casse, préfixe, suffixe et texte de remplacement. Expression du modèle montre la syntaxe ; Résultat actuel utilise les valeurs en direct. Insérer dans la ligne 1 ou 2 insère au curseur du champ. Enregistrer la page conserve le modèle modifié ; les réglages de cet assistant ne sont pas enregistrés. La saisie libre reste possible. F1 dans un champ de ligne ouvre l’info de formatage ; Échap la ferme.",
            "Sayfalar bölümünde Biçimlendirme düzenleyicisini açın. Süslü parantezsiz değişken anahtarı girin veya Değişkenlere göz at ile seçin. Değiştirilmemiş, Sayı, Yüzde veya Bayt, 0 ile 6 ondalık basamak ve isteğe bağlı harf boyutu, önek, sonek ve eksik değer metni seçin. Şablon ifadesi sözdizimini, Güncel sonuç canlı değerleri gösterir. 1. veya 2. satıra ekle, alanın imlecine ekler. Sayfayı kaydet değiştirilen şablonu kaydeder; yardımcı düzenleyici ayarları kaydedilmez. Serbest düzenleme korunur. Satır alanında F1 biçimlendirme ipucunu açar, Escape kapatır.",
            "На странице Страницы раскройте Редактор форматирования. Введите ключ без фигурных скобок или выберите через просмотр переменных. Выберите Без изменений, Число, Проценты или Байты, от 0 до 6 знаков, при необходимости регистр, префикс, суффикс и текст замены. Выражение шаблона показывает синтаксис; Текущий результат использует текущие данные. Вставка в строку 1 или 2 выполняется у её курсора. Сохраните страницу для сохранения шаблона; настройки вспомогательного редактора не сохраняются. Ручной ввод доступен. F1 в поле строки открывает подсказку, Escape закрывает её."],
        ["In these examples, replace Value with an actual variable key from Browse variables. The value before the arrow is source data, not text to enter in the line. Decimal commas follow German regional settings; English regional settings use a decimal point. Changing the app language does not change the operating system number format. Prefix and suffix are added after letter case. The editor rejects braces and | in its fields because they delimit template syntax; variable keys cannot contain spaces."] = [
            "Value in diesen Beispielen durch einen tatsächlichen Schlüssel aus dem Variablenbrowser ersetzen. Der Wert vor dem Pfeil ist ein Quellenwert und wird nicht als Text in die Zeile eingegeben. Das Dezimalkomma folgt deutschen Regionaleinstellungen; englische verwenden einen Punkt. Die App-Sprache ändert das Zahlenformat des Betriebssystems nicht. Präfix und Suffix werden nach der Groß-/Kleinschreibung ergänzt. Der Editor lehnt geschweifte Klammern und | ab, da sie Vorlagensyntax abgrenzen; Variablenschlüssel dürfen keine Leerzeichen enthalten.",
            "Remplacez Value par une clé réelle du navigateur. La valeur avant la flèche est une donnée source, pas le texte à saisir dans la ligne. La virgule correspond aux paramètres allemands ; les paramètres anglais utilisent un point. La langue de l’application ne change pas le format numérique du système. Préfixe et suffixe suivent la conversion de casse. Accolades et | sont refusés car ils délimitent la syntaxe ; les clés ne peuvent pas contenir d’espaces.",
            "Örneklerdeki Value yerine tarayıcıdaki gerçek anahtarı yazın. Okun önündeki değer kaynak verisidir, satıra girilecek metin değildir. Ondalık virgül Alman bölgesel ayarlarına bağlıdır; İngiliz ayarları nokta kullanır. Uygulama dili sistemin sayı biçimini değiştirmez. Önek ve sonek harf dönüşümünden sonra eklenir. Süslü parantezler ve | şablon ayırıcıları olduğundan reddedilir; anahtarlar boşluk içeremez.",
            "Замените Value реальным ключом из обозревателя. Значение перед стрелкой является исходными данными, а не текстом для ввода. Запятая соответствует немецким региональным настройкам, английские используют точку. Язык приложения не меняет числовой формат системы. Префикс и суффикс добавляются после преобразования регистра. Фигурные скобки и | запрещены как разделители синтаксиса; ключи не могут содержать пробелы."],
        ["If Value is missing, unknown or unavailable, {Value|fallback:--|number:2|suffix:°C} displays --. The fallback is returned directly; it is not formatted and receives no suffix. A valid value of 50.1234567 displays 50,12°C with German regional settings. Percent only adds the % symbol; it does not multiply the source by 100. Bytes divides by powers of 1024."] = [
            "Fehlt Value oder ist der Wert unknown beziehungsweise unavailable, zeigt {Value|fallback:--|number:2|suffix:°C} nur --. Der Ersatztext wird direkt zurückgegeben, ohne Formatierung oder Suffix. Ein gültiger Wert 50.1234567 ergibt bei deutschen Regionaleinstellungen 50,12°C. Prozent ergänzt nur das %-Zeichen, ohne mit 100 zu multiplizieren. Bytes teilt durch Potenzen von 1024.",
            "Si Value est absent, unknown ou unavailable, {Value|fallback:--|number:2|suffix:°C} affiche --. Le remplacement est renvoyé directement, sans formatage ni suffixe. La valeur 50.1234567 donne 50,12°C avec les paramètres allemands. Pourcentage ajoute seulement %, sans multiplier par 100. Octets divise par puissances de 1024.",
            "Value eksik, unknown veya unavailable ise {Value|fallback:--|number:2|suffix:°C} yalnızca -- gösterir. Yedek metin doğrudan döndürülür; biçimlendirilmez ve sonek eklenmez. Geçerli 50.1234567 değeri Alman bölgesel ayarlarında 50,12°C olur. Yüzde yalnızca % ekler, 100 ile çarpmaz. Bayt, 1024 kuvvetlerine böler.",
            "Если Value отсутствует, равен unknown или unavailable, {Value|fallback:--|number:2|suffix:°C} показывает --. Текст замены возвращается без форматирования и суффикса. Значение 50.1234567 при немецких настройках даёт 50,12°C. Проценты добавляют только %, без умножения на 100. Байты делят на степени 1024."],
        ["Click pixels or edit the eight binary rows. With programming on connect enabled, loading a glyph set also programs the connected display. Saved and sent states are separate. Previews show slot markers or spectrum bars."] = [
            "Pixel anklicken oder die acht Binärzeilen bearbeiten. Bei aktivierter Programmierung beim Verbinden wird ein geladener Zeichensatz auch an das verbundene Display gesendet. Gespeichert und gesendet sind getrennte Zustände. Vorschauen zeigen Speicherplatzmarkierungen oder Spektrumbalken.",
            "Cliquez sur les pixels ou modifiez les huit lignes binaires. Si la programmation à la connexion est activée, charger un jeu programme aussi l’écran connecté. Enregistré et envoyé sont distincts. Les aperçus montrent les emplacements ou les barres du spectre.",
            "Piksellere tıklayın veya sekiz ikili satırı düzenleyin. Bağlantıda programlama etkinse karakter kümesi yüklemek bağlı ekranı da programlar. Kaydedildi ve gönderildi durumları ayrıdır. Önizlemeler yuva işaretlerini veya spektrum çubuklarını gösterir.",
            "Нажимайте пиксели или редактируйте восемь двоичных строк. При включённом программировании при подключении загрузка набора также программирует подключённый дисплей. Сохранение и отправка отображаются отдельно. Предпросмотр показывает номера ячеек или столбцы спектра."],
        ["The condition fields follow the raw expression and selected page. Browse variables selects a current key for the condition. Invalid raw expressions remain editable. Save feedback appears beside the editor; a failed save keeps the draft."] = [
            "Die Bedingungsfelder folgen dem Ausdruck und der gewählten Seite. Der Variablenbrowser übernimmt einen aktuellen Schlüssel in die Bedingung. Ungültige Ausdrücke bleiben bearbeitbar. Der Speicherstatus steht am Editor; bei Fehlern bleibt der Entwurf erhalten.",
            "Les champs suivent l’expression et la page sélectionnée. Le navigateur choisit une clé actuelle pour la condition. Les expressions invalides restent modifiables. L’état d’enregistrement apparaît près de l’éditeur ; un échec conserve le brouillon.",
            "Koşul alanları ifadeyi ve seçili sayfayı izler. Değişken tarayıcısı koşul için güncel bir anahtar seçer. Geçersiz ifadeler düzenlenebilir. Kaydetme durumu düzenleyicide gösterilir; başarısız kaydetme taslağı korur.",
            "Поля условия следуют выражению и выбранной странице. Обозреватель переменных выбирает актуальный ключ для условия. Некорректные выражения остаются доступными для правки. Статус сохранения показан рядом с редактором; при ошибке черновик сохраняется."],
        ["The Winamp card shows stereo levels, twenty spectrum bands, the pipe and last snapshot time. Disconnection clears metadata and levels. SpectrumGlyphs uses the active spectrum glyph set; other sets use the text spectrum."] = [
            "Die Winamp-Karte zeigt Stereopegel, zwanzig Spektrumbänder, die Pipe und den Zeitpunkt des letzten Snapshots. Verbindungsverlust leert Metadaten und Pegel. SpectrumGlyphs verwendet den aktiven Spektrumzeichensatz; andere Sätze verwenden das Textspektrum.",
            "La carte Winamp affiche les niveaux stéréo, vingt bandes, le canal et l’heure du dernier instantané. La déconnexion efface métadonnées et niveaux. SpectrumGlyphs utilise le jeu de spectre actif ; les autres jeux utilisent le spectre texte.",
            "Winamp kartı stereo seviyeleri, yirmi spektrum bandını, kanalı ve son anlık görüntü zamanını gösterir. Bağlantı kesilince bilgiler ve seviyeler temizlenir. SpectrumGlyphs etkin spektrum karakter kümesini kullanır; diğer kümelerde metin spektrumu kullanılır.",
            "Карточка Winamp показывает стереоуровни, двадцать полос, канал и время последнего снимка. При отключении данные и уровни очищаются. SpectrumGlyphs использует активный спектральный набор; с другими наборами используется текстовый спектр."],
        ["Choose an available sensor directly or type a key, including a missing sensor. Curve points and raw text share decimal temperatures without rounding. Test tools contains simulations and preview controls. Physical authorization stays separate and is never saved."] = [
            "Verfügbaren Sensor direkt auswählen oder einen Schlüssel eingeben, auch für einen fehlenden Sensor. Kurvenpunkte und Rohtext verwenden dieselben Dezimaltemperaturen ohne Rundung. Prüfwerkzeuge enthalten Simulationen und Vorschauaktionen. Die physische Freigabe bleibt getrennt und wird nie gespeichert.",
            "Choisissez un capteur ou saisissez sa clé, même s’il est absent. Les points et le texte partagent les températures décimales sans arrondi. Les outils de test regroupent simulations et aperçus. L’autorisation physique reste séparée et n’est jamais enregistrée.",
            "Bir sensör seçin veya eksik sensör dahil bir anahtar yazın. Eğri noktaları ve metin yuvarlanmamış aynı ondalık sıcaklıkları kullanır. Test araçları simülasyonları ve önizlemeleri içerir. Fiziksel izin ayrıdır ve kaydedilmez.",
            "Выберите датчик или введите ключ, в том числе отсутствующего датчика. Точки и текст используют одинаковые температуры без округления. Средства проверки содержат симуляции и предпросмотр. Физическое разрешение остаётся отдельным и никогда не сохраняется."],
        ["Diagnostics includes version, UTC time, applied transport and port, last transmitted frame, source errors and four fan configurations. The virtual state is separate. Startup and crash traces persist in avalonia-errors.log without exception messages or tokens."] = [
            "Die Diagnose enthält Version, UTC-Zeit, angewendeten Transport und Port, zuletzt gesendeten Frame, Quellenfehler und vier Lüfterkonfigurationen. Der virtuelle Zustand wird getrennt angezeigt. Start- und Absturzspuren bleiben in avalonia-errors.log erhalten, ohne Ausnahmemeldungen oder Tokens.",
            "Le diagnostic contient version, heure UTC, transport et port appliqués, dernière trame envoyée, erreurs des sources et quatre configurations de ventilateurs. L’état virtuel est séparé. Les traces de démarrage et de panne restent dans avalonia-errors.log sans messages d’exception ni jetons.",
            "Tanılama sürümü, UTC zamanını, uygulanan bağlantı ve bağlantı noktasını, son gönderilen çerçeveyi, kaynak hatalarını ve dört fan yapılandırmasını içerir. Sanal durum ayrıdır. Başlangıç ve çökme izleri hata mesajı veya belirteç olmadan avalonia-errors.log içinde saklanır.",
            "Диагностика содержит версию, время UTC, применённый транспорт и порт, последний отправленный кадр, ошибки источников и настройки четырёх вентиляторов. Виртуальное состояние показано отдельно. Трассы запуска и сбоев хранятся в avalonia-errors.log без сообщений исключений и токенов."],
        ["Autostart uses the Windows user registry or a Linux XDG autostart entry. Windows closes to tray; Linux closes the application and keeps minimized windows in the taskbar. Tray menus offer Open and Exit. A second launch activates the existing instance. F1 opens help for the current section."] = [
            "Der Autostart verwendet die Windows-Benutzerregistrierung oder einen Linux-XDG-Autostarteintrag. Windows schließt in den Infobereich; Linux beendet die Anwendung beim Schließen und hält minimierte Fenster in der Taskleiste. Das Tray-Menü bietet Öffnen und Beenden. Ein zweiter Start aktiviert die vorhandene Instanz. F1 öffnet die Hilfe zum aktuellen Bereich.",
            "Le démarrage automatique utilise le registre utilisateur Windows ou une entrée XDG Linux. Sous Windows, fermer réduit dans la zone de notification ; sous Linux, fermer quitte l’application et les fenêtres réduites restent dans la barre des tâches. Le menu de notification propose Ouvrir et Quitter. Un second lancement active l’instance existante. F1 ouvre l’aide de la section actuelle.",
            "Otomatik başlatma Windows kullanıcı kayıt defterini veya Linux XDG başlangıç girdisini kullanır. Windows kapatıldığında tepsiye küçülür; Linux kapatıldığında uygulamadan çıkar ve küçültülmüş pencereleri görev çubuğunda tutar. Tepsi menüsü Aç ve Çıkış sunar. İkinci başlatma mevcut örneği etkinleştirir. F1 geçerli bölümün yardımını açar.",
            "Автозапуск использует реестр пользователя Windows или запись XDG Linux. В Windows закрытие сворачивает в область уведомлений; в Linux закрытие завершает приложение, а свёрнутые окна остаются на панели задач. Меню области уведомлений предлагает Открыть и Выход. Повторный запуск активирует существующий экземпляр. F1 открывает справку текущего раздела."],
        ["Token storage"] = ["Tokenspeicherung", "Stockage du jeton", "Belirteç depolama", "Хранение токена"],
        ["Windows uses DPAPI. Linux uses the desktop keyring through secret-tool. Local AES storage requires explicit selection; the key is stored beside the encrypted token. Keyring errors are displayed without switching storage automatically. Disabling Home Assistant stops the source and removes the token from the selected store. Switching back to the keyring migrates local files only after verifying the saved token."] = [
            "Windows verwendet DPAPI. Linux verwendet den Desktop-Schlüsselbund über secret-tool. Lokale AES-Speicherung muss ausdrücklich ausgewählt werden; der Schlüssel liegt neben dem verschlüsselten Token. Schlüsselbundfehler werden angezeigt, ohne die Speicherart automatisch zu wechseln. Deaktivieren stoppt die Quelle und entfernt das Token aus dem gewählten Speicher. Beim Wechsel zurück zum Schlüsselbund werden lokale Dateien erst nach Prüfung des gespeicherten Tokens entfernt.",
            "Windows utilise DPAPI. Linux utilise le trousseau du bureau via secret-tool. Le stockage AES local doit être choisi explicitement ; la clé se trouve à côté du jeton chiffré. Les erreurs du trousseau sont affichées sans changement automatique de stockage. Désactiver Home Assistant arrête la source et supprime le jeton du stockage sélectionné. Le retour au trousseau ne supprime les fichiers locaux qu’après vérification du jeton enregistré.",
            "Windows DPAPI kullanır. Linux, secret-tool üzerinden masaüstü anahtarlığını kullanır. Yerel AES depolama açıkça seçilmelidir; anahtar şifreli belirtecin yanında saklanır. Anahtarlık hataları otomatik depolama değişikliği olmadan gösterilir. Home Assistant devre dışı bırakıldığında kaynak durdurulur ve seçili depodaki belirteç silinir. Anahtarlığa dönüşte yerel dosyalar yalnızca kaydedilen belirteç doğrulandıktan sonra silinir.",
            "Windows использует DPAPI. Linux использует хранилище ключей через secret-tool. Локальное хранение AES требует явного выбора; ключ находится рядом с зашифрованным токеном. Ошибки хранилища показываются без автоматического переключения. Отключение Home Assistant останавливает источник и удаляет токен из выбранного хранилища. При возврате к системному хранилищу локальные файлы удаляются только после проверки сохранённого токена."],
